var ghgoldenRootRE = regexp.MustCompile(`^/tmp/ghgolden-[^/]+`)

var ghGolden map[string]any

func loadGhGolden(t *testing.T) map[string]any {
	t.Helper()
	if ghGolden != nil {
		return ghGolden
	}
	data, err := os.ReadFile("testdata/githubpipeline.golden.json")
	if err != nil {
		t.Fatalf("golden file: %v", err)
	}
	var g map[string]any
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatalf("golden json: %v", err)
	}
	ghGolden = g
	return g
}

func ghSection(t *testing.T, name string) map[string]any {
	t.Helper()
	v, ok := loadGhGolden(t)[name].(map[string]any)
	if !ok {
		t.Fatalf("golden section %q missing or not an object", name)
	}
	return v
}

// ghFold folds BOTH sides' tempdir roots (the generator's
// /tmp/ghgolden-XXXX and the Go test's t.TempDir()) to "<TMP>".
func ghFold(s, root string) string {
	out := ghgoldenRootRE.ReplaceAllString(s, "<TMP>")
	if root != "" {
		out = strings.ReplaceAll(out, root, "<TMP>")
	}
	return out
}

// cmpGh byte-compares through the canonical Python dumps.
func cmpGh(t *testing.T, what string, got, want any, root string) {
	t.Helper()
	g := storage.PyDumps(normGh(got, root))
	w := storage.PyDumps(normGh(want, ""))
	if g != w {
		t.Fatalf("%s diverges from the reference golden:\n--- go ---\n%s"+
			"\n--- reference ---\n%s", what, g, w)
	}
}

func normGh(v any, root string) any {
	switch t := v.(type) {
	case string:
		return ghFold(t, root)
	case []string:
		out := make([]any, len(t))
		for i, s := range t {
			out[i] = ghFold(s, root)
		}
		return out
	case map[string]string:
		out := map[string]any{}
		for k, s := range t {
			out[k] = ghFold(s, root)
		}
		return out
	case []map[string]string:
		out := make([]any, len(t))
		for i, m := range t {
			out[i] = normGh(m, root)
		}
		return out
	case int:
		return float64(t)
	case int64:
		return float64(t)
	case bool:
		return t
	case float64:
		return t
	case json.Number:
		f, _ := t.Float64()
		return f
	case nil:
		return nil
	case map[string]any:
		out := map[string]any{}
		for k, val := range t {
			out[k] = normGh(val, root)
		}
		return out
	case []any:
		out := make([]any, len(t))
		for i, val := range t {
			out[i] = normGh(val, root)
		}
		return out
	default:
		return t
	}
}

// goldenRunner builds the frozen-clock runner the report writers need.
func goldenRunner(t *testing.T, config map[string]any) *Runner {
	t.Helper()
	dryrun.Disable()
	dryrun.Clear()
	t.Cleanup(func() { dryrun.Disable() })
	if config == nil {
		config = map[string]any{}
	}
	r := NewRunner(config)
	r.Clock = func() time.Time {
		return time.Date(2026, 10, 17, 12, 0, 0, 0, time.Local)
	}
	return r
}

// ghSeedProcessedLog mirrors the generator's _processed_log rows.
