// ghNoteStateRun mirrors the generator's NOTE_STATE_RUN dict.
func ghNoteStateRun() map[string]*notestate.RunResult {
	return map[string]*notestate.RunResult{
		"github": {
			Baseline: intp(128),
			Changes: notestate.Changes{
				Unmanaged: []notestate.UnmanagedNote{{Path: "Loose.md"}},
				Edited: []notestate.Edited{
					{Path: "Dev-Tools/edited.md"},
					{Path: "Media/edited2.md"},
				},
				Unmapped: []notestate.UnmappedNote{
					{Folder: "Mystery", Path: "Mystery/note.md"},
				},
				Unknown: []notestate.Unknown{{Path: "Weird.md"}},
			},
			Applied: notestate.Summary{
				MovedApplied:  2,
				MovedUnmapped: 1,
				Dismissed:     1,
				Corrections: []notestate.CorrectionRecord{
					{SourceURL: "https://github.com/a/one",
						FromCategory: strp("Dev-Tools"),
						ToCategory:   "Media", ToPath: "Media/one.md"},
					{SourceURL: "https://github.com/a/two",
						FromCategory: strp("Dev-Tools"),
						ToCategory:   "Media", ToPath: "Media/two.md"},
				},
			},
		},
	}
}

func strp(s string) *string { return &s }
func intp(i int) *int       { return &i }

// summaryToMap renders a *batch.BatchSummary as the reference's dict.
func summaryToMap(s *batch.BatchSummary) map[string]any {
	var websites any
	if s.Websites != nil {
		websites = map[string]any{
			"processed": s.Websites.Processed, "review": s.Websites.Review,
			"skipped": s.Websites.Skipped, "failed": s.Websites.Failed,
		}
	}
	return map[string]any{
		"stopped":          s.Stopped,
		"github_processed": s.GithubProcessed,
		"github_total":     s.GithubTotal,
		"new_notes":        s.NewNotes,
		"websites":         websites,
		"failed_links":     s.FailedLinks,
		"report_path":      s.ReportPath,
		"summary_path":     s.SummaryPath,
	}
}

// ---------------------------------------------------------------------------
// 1) the scorecard legs.
// ---------------------------------------------------------------------------

func TestGoldenBatchSummary(t *testing.T) {
	bs := ghSection(t, "build_batch_summary")

	// clean
	want := bs["clean"].(map[string]any)
	got := summaryToMap(batch.BuildBatchSummary(false, 18, 20, 18, nil,
		nil, "/v/_processing_report_x.md", "/v/_summary.txt"))
	cmpGh(t, "build_batch_summary.clean", got, want, "")

	// stopped
	want = bs["stopped"].(map[string]any)
	got = summaryToMap(batch.BuildBatchSummary(true, 3, 620, 0, nil, nil,
		"", ""))
	cmpGh(t, "build_batch_summary.stopped", got, want, "")

	// websites counters (the phase's other counters drop on the floor)
	want = bs["websites"].(map[string]any)
	ws := &batch.WebsitesCounters{Processed: 7, Review: 2, Skipped: 1,
		Failed: 0}
	got = summaryToMap(batch.BuildBatchSummary(false, 0, 0, 0, ws, nil,
		"", ""))
	cmpGh(t, "build_batch_summary.websites", got, want, "")

	// failed links from the manifest
	dir := t.TempDir()
	tracker := batch.NewLinkTracker(dir)
	tracker.Manifest.Links = []*batch.ManifestLink{
		{URL: "https://x/0", Normalized: "x/0", Type: "github",
			Status: "processed"},
		{URL: "https://x/1", Normalized: "x/1", Type: "github",
			Status: "processed"},
		{URL: "https://x/2", Normalized: "x/2", Type: "github",
			Status: "failed"},
		{URL: "https://x/3", Normalized: "x/3", Type: "github",
			Status: "skipped"},
		{URL: "https://x/4", Normalized: "x/4", Type: "github",
			Status: "failed"},
	}
	want = bs["failed_links"].(map[string]any)
	got = summaryToMap(batch.BuildBatchSummary(false, 0, 0, 0, nil,
		tracker, "", ""))
	cmpGh(t, "build_batch_summary.failed_links", got, want, "")

	// no tracker
	want = bs["no_tracker"].(map[string]any)
	got = summaryToMap(batch.BuildBatchSummary(false, 0, 0, 0, nil, nil,
		"", ""))
	cmpGh(t, "build_batch_summary.no_tracker", got, want, "")

	// the broken manifest (nil manifest reads as zero failed)
	want = bs["broken_manifest"].(map[string]any)
	broken := &batch.LinkTracker{Manifest: nil}
	got = summaryToMap(batch.BuildBatchSummary(false, 0, 0, 0, nil, broken,
		"", ""))
	cmpGh(t, "build_batch_summary.broken_manifest", got, want, "")
}

// ---------------------------------------------------------------------------
// 2) the summary log writer (bytes + rotation).
