func goldenSummaryFlow(t *testing.T, key string, seededOld int) {
	t.Helper()
	flow := ghSection(t, key)
	dir := t.TempDir()
	vault := filepath.Join(dir, "vault")
	flowName := strings.TrimPrefix(key, "summary_log_")
	reports := filepath.Join(dir, "reports-"+flowName)
	for _, d := range []string{vault, reports} {
		if err := os.MkdirAll(d, 0o755); err != nil {
			t.Fatal(err)
		}
	}
	websitesOn := key == "summary_log_websites_on"
	if seededOld > 0 {
		names := []string{
			"processing_summary_20260101_010101.txt",
			"processing_summary_20260202_020202.txt",
			"processing_summary_20260303_030303.txt",
		}
		for i := 0; i < seededOld && i < len(names); i++ {
			os.WriteFile(filepath.Join(reports, names[i]),
				[]byte("OLD\n"), 0o644)
		}
	}
	r := goldenRunner(t, map[string]any{
		"vault_path": vault, "reports_dir": reports,
		"summary_keep_last": 2,
		"pipelines":         map[string]any{"websites": websitesOn},
	})
	r.Total = 5
	r.Processed = 2
	r.processedLog = ghSeedProcessedLog(vault)
	r.NonGithubURLs = []string{"https://x.com/post/1",
		"https://example.com/tool"}
	path := r.GenerateSummaryLog()
	if path == "" {
		t.Fatalf("%s: no summary path", key)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if got, want := string(data), flow["bytes"].(string); got != want {
		t.Fatalf("%s bytes diverge:\n--- go ---\n%s\n--- reference ---\n%s",
			key, got, want)
	}
	// The path + the rotation survivors.
	cmpGh(t, key+".path", map[string]any{"path": path},
		map[string]any{"path": flow["path"]}, dir)
	entries, _ := os.ReadDir(reports)
	var survivors []string
	for _, e := range entries {
		if strings.HasPrefix(e.Name(), "processing_summary_") &&
			strings.HasSuffix(e.Name(), ".txt") {
			survivors = append(survivors, e.Name())
		}
	}
	sortStrings(survivors)
	cmpGh(t, key+".survivors", survivors, flow["survivors"], "")
}

func TestGoldenSummaryLogWebsitesOff(t *testing.T) {
	goldenSummaryFlow(t, "summary_log_websites_off", 3)
}

func TestGoldenSummaryLogWebsitesOn(t *testing.T) {
	goldenSummaryFlow(t, "summary_log_websites_on", 0)
}

