func goldenFinalReport(t *testing.T, key string, rich bool) {
	t.Helper()
	flow := ghSection(t, key)
	dir := t.TempDir()
	vault := filepath.Join(dir, "vault")
	reports := filepath.Join(dir, "reports")
	for _, d := range []string{vault, reports} {
		if err := os.MkdirAll(d, 0o755); err != nil {
			t.Fatal(err)
		}
	}
	websitesOn := rich
	config := map[string]any{
		"vault_path": vault, "reports_dir": reports,
		"pipelines":          map[string]any{"websites": websitesOn},
		"website_vault_path": "/wv",
	}
	r := goldenRunner(t, config)
	r.Total = 5
	r.Processed = 2
	r.processedLog = ghSeedProcessedLog(vault)
	r.IntakeDuplicates = 0
	r.RawURLCount = 0
	if rich {
		r.IntakeDuplicates = 2
		r.RawURLCount = 14
		r.BotSource = true
		r.NonGithubURLs = []string{"https://x.com/post/1",
			"https://example.com/tool", "https://reddit.com/r/golang"}
		r.websites = &WebsiteSummary{
			Counters: map[string]int{"processed": 2, "review": 1,
				"upgraded": 1, "retried": 3, "skipped": 1, "failed": 0},
			Results: []WebsiteResultEntry{
				{URL: "https://example.com/tool", Outcome: "processed",
					Category: "Design", Subcategory: "Assets & Resources"},
				{URL: "https://other.example/", Outcome: "review",
					Error: "fetch refused"},
			},
			Vault: "/wv",
		}
	} else {
		r.BotSource = false
		r.NonGithubURLs = []string{"https://youtube.com/watch?v=x"}
	}
	r.DismissedSkipped = 1
	r.NoteStateRun = ghNoteStateRun()
	path := r.GenerateFinalReport(ghTrackerReport())
	if path == "" {
		t.Fatalf("%s: no report path", key)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if got, want := string(data), flow["bytes"].(string); got != want {
		t.Fatalf("%s bytes diverge:\n--- go ---\n%s\n--- reference ---\n%s",
			key, got, want)
	}
}

