func TestGoldenLLMLadder(t *testing.T) {
	section := ghSection(t, "llm_ladder")
	oldWD, _ := os.Getwd()
	cwd := t.TempDir()
	if err := os.Chdir(cwd); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.Chdir(oldWD) })

	answers := []string{
		"I am sorry, I cannot answer in JSON.",
		"still not json at all",
		"This is a two sentence answer. It is short.",
	}
	var calls []map[string]any
	orig := callCloudLLM
	callCloudLLM = func(apiURL, apiKey, model string,
		messages []llmclient.Message, timeoutS float64,
		opts *llmclient.ChatOptions) (string, error) {
		jsonMode := opts == nil || opts.JSONMode
		roles := []string{}
		for _, m := range messages {
			roles = append(roles, m.Role)
		}
		ans := ""
		if len(calls) < len(answers) {
			ans = answers[len(calls)]
		}
		calls = append(calls, map[string]any{
			"model": model, "json_mode": jsonMode, "roles": roles})
		return ans, nil
	}
	t.Cleanup(func() { callCloudLLM = orig })

	r := goldenRunner(t, map[string]any{
		"llm_provider":  "cloud",
		"cloud_api_url": "http://127.0.0.1:9/v1",
		"cloud_api_key": "", "cloud_model": "base-model",
	})
	result, err := r.LLMAnalyze("base-model", "ladder-repo", "d", nil,
		"o", 1, 2, "")
	if err != nil {
		t.Fatalf("ladder: %v", err)
	}
	cmpGh(t, "llm_ladder.calls", calls, section["calls"], "")
	cmpGh(t, "llm_ladder.result", result, section["result"], "")
}

