// credRepoStub is the _repo_stub twin.
type credRepoStub struct {
	hasIssues, hasLicense, hasWiki bool
	description                    string
	readme                         bool
}

func (c credRepoStub) toDoc() CredibilityDocSource {
	return CredibilityDocSource{
		HasIssues: c.hasIssues, HasLicense: c.hasLicense,
		HasWiki: c.hasWiki, Description: c.description,
		ReadmeFetchedAny: c.readme,
	}
}

func fullStub() credRepoStub {
	return credRepoStub{true, true, true,
		"A description that is long enough to count.", true}
}

func TestGoldenCredibility(t *testing.T) {
	section := ghSection(t, "credibility")
	cases := []struct {
		key                 string
		org, stars, commits int
		doc                 CredibilityDocSource
	}{
		{"all_bonuses", 10, 20000, 80, fullStub().toDoc()},
		{"no_doc", 3, 0, 0, credRepoStub{false, false, false, "", false}.toDoc()},
		{"mid_org", 7, 5500, 25, fullStub().toDoc()},
		{"ladder_stars.0", 3, 0, 10, fullStub().toDoc()},
		{"ladder_stars.11", 3, 11, 10, fullStub().toDoc()},
		{"ladder_stars.101", 3, 101, 10, fullStub().toDoc()},
		{"ladder_stars.1001", 3, 1001, 10, fullStub().toDoc()},
		{"ladder_stars.5001", 3, 5001, 10, fullStub().toDoc()},
		{"ladder_stars.10001", 3, 10001, 10, fullStub().toDoc()},
		{"ladder_commits.0", 3, 500, 0, fullStub().toDoc()},
		{"ladder_commits.6", 3, 500, 6, fullStub().toDoc()},
		{"ladder_commits.21", 3, 500, 21, fullStub().toDoc()},
		{"ladder_commits.51", 3, 500, 51, fullStub().toDoc()},
		{"famous_floor", 10, 0, 0,
			credRepoStub{false, false, false, "", false}.toDoc()},
		{"fractional", 3, 100, 10,
			credRepoStub{true, true, true, "short", true}.toDoc()},
	}
	for _, tc := range cases {
		want, ok := section[tc.key]
		if !ok {
			if strings.HasPrefix(tc.key, "ladder_") {
				ladder := section[strings.SplitN(tc.key, ".", 2)[0]].(map[string]any)
				want = ladder[strings.SplitN(tc.key, ".", 2)[1]]
			} else {
				t.Fatalf("credibility case %q missing", tc.key)
			}
		}
		got := CalculateCredibility(tc.org, tc.stars, tc.commits, tc.doc)
		cmpGh(t, "credibility."+tc.key, got, want, "")
	}
}

func TestGoldenOrgReputation(t *testing.T) {
	section := ghSection(t, "org_reputation")
	cases := map[string]string{
		"microsoft": "microsoft", "cloud_sub": "GoogleCloudLabs",
		"mid": "HuggingFaceHQ", "spaced": "Some Org Inc",
		"solo": "solo", "aws": "my-aws-team",
	}
	for key, org := range cases {
		cmpGh(t, "org_reputation."+key, OrgReputation(org), section[key], "")
	}
}

func TestGoldenPickBestModel(t *testing.T) {
	section := ghSection(t, "pick_best_model")
	cases := []struct {
		key        string
		configured string
		available  []string
	}{
		{"empty", "", nil},
		{"single", "qwen3:8b", []string{"only/one"}},
		{"embeds_dropped", "qwen3:8b",
			[]string{"nomic-embed-text", "qwen3:4b-instruct"}},
		{"same_family", "qwen3:8b",
			[]string{"llama3.2:3b", "qwen3.2:1b", "mistral:7b"}},
		{"same_size", "Qwen3.8-27B-GSQ",
			[]string{"qwen3:27b", "qwen3:8b", "llama3:27b"}},
		{"tiebreak_biggest", "missing-model",
			[]string{"a:1b", "b:14b", "c:7b"}},
		{"tiebreak_longest", "missing-model",
			[]string{"x:7b", "x:7b-instruct-q4"}},
	}
	for _, tc := range cases {
		cmpGh(t, "pick_best_model."+tc.key,
			PickBestModel(tc.configured, tc.available), section[tc.key], "")
	}
}

// sortStrings (the undo walk's helper) — the survivors comparison uses it.
func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}
